package com.estoqueinteligente.report;
import java.time.LocalDate;import java.util.List;import org.springframework.stereotype.Service;import com.estoqueinteligente.product.*;
@Service public class ReportService{private final ProductService products;public ReportService(ProductService products){this.products=products;}public List<StockReportResponse> stock(){return products.findAll().stream().map(StockReportResponse::new).toList();}public List<LowStockReportResponse> lowStock(){return products.findLowStock().stream().map(LowStockReportResponse::new).toList();}public List<ExpiringReportResponse> expiring(){LocalDate today=LocalDate.now();return products.findByCurrentStatus(ProductStatus.VENCENDO).stream().map(p->new ExpiringReportResponse(p,today)).toList();}public List<ExpiredReportResponse> expired(){LocalDate today=LocalDate.now();return products.findByCurrentStatus(ProductStatus.VENCIDO).stream().map(p->new ExpiredReportResponse(p,today)).toList();}public List<PurchaseSuggestionResponse> purchaseSuggestion(){return products.findLowStock().stream().map(PurchaseSuggestionResponse::new).toList();}}
